{"path": "/workspace/target/src/enrich.py", "content": """"Zone / rate-class enrichment for green-taxi serving.

Serving requests do not arrive with the tidy dtypes of the offline parquet: the
identifier and code columns show up as ints, floats, floats-as-strings with padding
(``" 74.0 "``), or free text that is not a code at all.  The lookup tables shipped in
``data/`` are authoritative for how each published identifier resolves:

``taxi_zone_lookup.csv``
    every published ``LocationID`` resolves through its own row.  A blank ``Borough``
    or ``service_zone`` falls back to that row's ``Zone`` label; an identifier still
    without a value after that fallback, or one absent from the table, has no zone
    and is published as ``UNKNOWN``.

``rate_codes.csv``
    lists code 99 (``unknown_reported`` / ``unspecified``) alongside the ordinary
    codes.  TLC publishes a trip whose rate was not reported with ``RatecodeID``
    absent, so a missing code resolves to 99.  A code outside the codebook has no
    rate class and is published as ``UNKNOWN``.
"""

from __future__ import annotations

import math

import numpy as np
import pandas as pd

from . import time_contract

UNKNOWN = "UNKNOWN"

ZONE_COLUMNS = ["pu_borough", "pu_service_zone", "do_borough", "do_service_zone"]
RATE_COLUMNS = ["rate_class", "fare_basis"]
ENRICHED_COLUMNS = ZONE_COLUMNS + RATE_COLUMNS
TEMPORAL_COLUMNS = list(time_contract.COLUMNS)
CONTRACT_COLUMNS = ENRICHED_COLUMNS + TEMPORAL_COLUMNS

MISSING_RATE_CODE = 99


def _clean_text(value) -> str:
    """Trimmed text for a lookup cell, or '' when the cell carries no value."""
    if value is None:
        return ""
    if isinstance(value, float) and math.isnan(value):
        return ""
    try:
        if value is pd.NA or (not isinstance(value, str) and pd.isna(value)):
            return ""
    except (TypeError, ValueError):
        pass
    return str(value).strip()


def _coerce_identifier(value):
    """Parse a published identifier / code into an int, or None when it is not one."""
    if value is None:
        return None
    if isinstance(value, (bool, np.bool_)):
        return None
    if isinstance(value, (int, np.integer)):
        return int(value)
    if isinstance(value, (float, np.floating)):
        number = float(value)
    else:
        if isinstance(value, bytes):
            try:
                value = value.decode()
            except Exception:
                return None
        if not isinstance(value, str):
            try:
                if pd.isna(value):
                    return None
            except (TypeError, ValueError):
                pass
            try:
                number = float(value)
            except (TypeError, ValueError):
                return None
        else:
            text = value.strip()
            if not text:
                return None
            try:
                number = float(text)
            except ValueError:
                return None
    if not math.isfinite(number):
        return None
    if abs(number - round(number)) > 1e-9:
        # A fractional value is not a published identifier.
        return None
    return int(round(number))


def _identifiers(series: pd.Series) -> pd.Series:
    return pd.Series([_coerce_identifier(v) for v in series],
                     index=series.index, dtype="object")


def zone_maps(zones: pd.DataFrame) -> tuple[dict, dict]:
    """Return {LocationID: borough}, {LocationID: service_zone} with Zone fallback."""
    borough: dict[int, str] = {}
    service: dict[int, str] = {}
    for _, row in zones.iterrows():
        key = _coerce_identifier(row.get("LocationID"))
        if key is None:
            continue
        label = _clean_text(row.get("Zone"))
        b = _clean_text(row.get("Borough")) or label
        s = _clean_text(row.get("service_zone")) or label
        borough[key] = b or UNKNOWN
        service[key] = s or UNKNOWN
    return borough, service


def rate_maps(rates: pd.DataFrame) -> tuple[dict, dict]:
    rate_class: dict[int, str] = {}
    fare_basis: dict[int, str] = {}
    for _, row in rates.iterrows():
        key = _coerce_identifier(row.get("code"))
        if key is None:
            continue
        rate_class[key] = _clean_text(row.get("rate_class")) or UNKNOWN
        fare_basis[key] = _clean_text(row.get("fare_basis")) or UNKNOWN
    return rate_class, fare_basis


def _lookup(ids: pd.Series, table: dict) -> pd.Series:
    return pd.Series(
        [UNKNOWN if key is None else table.get(key, UNKNOWN) for key in ids],
        index=ids.index, dtype="object")


def enrich(trips: pd.DataFrame, zones: pd.DataFrame, rates: pd.DataFrame) -> pd.DataFrame:
    borough_map, service_map = zone_maps(zones)
    rate_class_map, fare_basis_map = rate_maps(rates)

    out = trips.copy()

    pu = _identifiers(trips["PULocationID"]) if "PULocationID" in trips else pd.Series(
        [None] * len(trips), index=trips.index, dtype="object")
    do = _identifiers(trips["DOLocationID"]) if "DOLocationID" in trips else pd.Series(
        [None] * len(trips), index=trips.index, dtype="object")

    out["pu_borough"] = _lookup(pu, borough_map)
    out["pu_service_zone"] = _lookup(pu, service_map)
    out["do_borough"] = _lookup(do, borough_map)
    out["do_service_zone"] = _lookup(do, service_map)

    if "RatecodeID" in trips:
        raw_codes = trips["RatecodeID"]
    else:
        raw_codes = pd.Series([None] * len(trips), index=trips.index, dtype="object")

    codes = []
    for raw in raw_codes:
        code = _coerce_identifier(raw)
        if code is None and _is_absent(raw):
            # Rate not reported: TLC publishes the column absent, codebook says 99.
            code = MISSING_RATE_CODE
        codes.append(code)
    codes = pd.Series(codes, index=trips.index, dtype="object")

    out["rate_class"] = _lookup(codes, rate_class_map)
    out["fare_basis"] = _lookup(codes, fare_basis_map)

    for column in ENRICHED_COLUMNS:
        out[column] = out[column].astype(str)
    return out


def _is_absent(value) -> bool:
    if value is None:
        return True
    if isinstance(value, float) and math.isnan(value):
        return True
    if isinstance(value, str) and not value.strip():
        return True
    try:
        if value is pd.NA or (not isinstance(value, str) and pd.isna(value)):
            return True
    except (TypeError, ValueError):
        pass
    return False


def enrich_contract(trips: pd.DataFrame, zones: pd.DataFrame,
                    rates: pd.DataFrame) -> pd.DataFrame:
    """Enrichment plus the local-time contract columns."""
    out = enrich(trips, zones, rates)
    if "lpep_pickup_datetime" in out:
        source = out["lpep_pickup_datetime"]
    else:
        source = pd.Series([None] * len(out), index=out.index, dtype="object")
    temporal = time_contract.derive(source)
    for column in TEMPORAL_COLUMNS:
        out[column] = temporal[column].astype(str)
    return out
"}

