from pathlib import Path

import pandas as pd

from . import enrich, features, model, time_contract

DATA = Path(__file__).resolve().parent.parent / "data"

CONTRACT_COLUMNS = list(enrich.CONTRACT_COLUMNS)


def load_reference() -> tuple[pd.DataFrame, pd.DataFrame]:
    zones = pd.read_csv(DATA / "taxi_zone_lookup.csv", keep_default_na=False, na_values=[])
    rates = pd.read_csv(DATA / "rate_codes.csv", keep_default_na=False, na_values=[])
    return zones, rates


def _as_frame(trips) -> pd.DataFrame:
    if isinstance(trips, pd.DataFrame):
        return trips
    if isinstance(trips, dict):
        return pd.DataFrame([trips])
    if isinstance(trips, (list, tuple)):
        return pd.DataFrame(list(trips))
    raise TypeError(f"unsupported request payload: {type(trips)!r}")


def enrich_batch(trips) -> pd.DataFrame:
    zones, rates = load_reference()
    return enrich.enrich_contract(_as_frame(trips), zones, rates)


def contract_batch(trips) -> pd.DataFrame:
    """Only the contract columns, in contract order, as strings."""
    out = enrich_batch(trips)
    return out.reindex(columns=CONTRACT_COLUMNS).astype(str)


def build_matrix(trips) -> pd.DataFrame:
    zones, rates = load_reference()
    return features.build(_as_frame(trips), zones, rates)


def score_batch(estimator, trips) -> pd.Series:
    matrix = build_matrix(trips)
    return pd.Series(estimator.predict(matrix), name="predicted_duration_minutes")


def predict(estimator, trips):
    return score_batch(estimator, trips)
"}

