    lists code 99 (``unknown_reported`` / ``unspecified``) alongside the ordinary
    codes.  TLC publishes a trip whose rate was not reported with ``RatecodeID``
    absent, so a missing code resolves to 99.  A code outside the codebook has no
    rate class and is published as ``UNKNOWN``.
"""

from __future__ import annotations

import math

import numpy as np
import pandas as pd

from . import time_contract

UNKNOWN = "UNKNOWN"

ZONE_COLUMNS = ["pu_borough", "pu_service_zone", "do_borough", "do_service_zone"]
RATE_COLUMNS = ["rate_class", "fare_basis"]
ENRICHED_COLUMNS = ZONE_COLUMNS + RATE_COLUMNS
TEMPORAL_COLUMNS = list(time_contract.COLUMNS)
CONTRACT_COLUMNS = ENRICHED_COLUMNS + TEMPORAL_COLUMNS

MISSING_RATE_CODE = 99

# Serving payloads have been observed carrying the pickup timestamp under several
# names; the TLC green-taxi column is the canonical one.
PICKUP_COLUMNS = ["lpep_pickup_datetime", "pickup_datetime", "tpep_pickup_datetime",
                  "pickup_ts", "pickup"]


def pickup_series(frame: pd.DataFrame) -> pd.Series:
    for name in PICKUP_COLUMNS:
        if name in frame.columns:
            return frame[name]
    return pd.Series([None] * len(frame), index=frame.index, dtype="object")


def _clean_text(value) -> str:
    """Trimmed text for a lookup cell, or '' when the cell carries no value."""
    if value is None:
        return ""
    if isinstance(value, float) and math.isnan(value):
        return ""
    try:
        if value is pd.NA or (not isinstance(value, str) and pd.isna(value)):
            return ""
    except (TypeError, ValueError):
        pass
